export interface StoryBible {
  genre: string;
  tone: string;
  setting: string;
  protagonist: string;
  motif: string; // light theming drawn from the user's work
  arc: string[]; // planned beats
  seeds: { narrator: string; twist: string };
}

/** A 60-second primer: a few key ideas plus one warm-up check (decision log 2026-10-18). Server-side record. */
export interface Primer {
  ideas: string[]; // 3-4 short markdown lines
  check: { question: string; options: string[]; correctIndex: number; why: string[] };
  createdAt: number;
  dismissed?: boolean;
  answer?: { choice: number; correct: boolean };
}

export interface StoryChapter {
  id: string;
  trigger: string; // e.g. "boss:<id>" | "wrapup"
  title: string;
  text: string;
  summary: string;
  createdAt: number;
}

export interface StoryState {
  bible?: StoryBible;
  chapters: StoryChapter[];
}

export interface Session {
export interface CreateSessionResponse { sessionId: string }

// GET /api/session/[id]
export interface SessionView {
  id: string;
  title: string;
  intent: Intent;
  sketch?: SessionSketch;
  status: "active" | "wrapped";
  createdAt: number;
  endsAt: number; // createdAt + intent.minutes
  transcript: TranscriptItem[];
  moments: Record<string, MomentView>;
  bosses: Record<string, BossView>;
  chapters: Record<string, StoryChapter>;
  /** A boss is due: show the "Take it on / Keep working" offer. */
  bossOfferPending?: boolean;
  primer?: PrimerView;
}

/** Client view of the novice primer: the check's answer key only after it's answered. */
export function toSessionView(s: Session, transcript: TranscriptItem[], moments: MomentRecord[], bosses: BossState[]): SessionView {
  return {
    id: s.id,
    title: s.title,
    intent: s.intent,
    sketch: s.sketch,
    status: s.status,
    createdAt: s.createdAt,
    endsAt: s.createdAt + s.intent.minutes * 60_000,
    transcript,
    moments: Object.fromEntries(moments.map((m) => [m.id, toMomentView(m)])),
    bosses: Object.fromEntries(bosses.map((b) => [b.id, toBossView(b, moments)])),
    chapters: Object.fromEntries(s.story.chapters.map((c) => [c.id, c])),
    bossOfferPending: Boolean(s.engine.bossOfferPending) && bosses.every((b) => b.outcome),
    primer: s.primer ? toPrimerView(s.primer) : undefined,
  };
}

