      setPathBusy(true);
      try {
        const res = await apiPost<PathResponse>(`/api/session/${sessionId}/path`, { from, to });
        update((v) => ({ ...v, path: res.path }));
      } catch {
        /* the order stays as it was */
      } finally {
        setPathBusy(false);
      }
    },
    [sessionId, update],
  );

  // ---- settings ----''')
sub(uw, "    wrapUp,\n    reading,\n", "    wrapUp,\n    reading,\n    movePart,\n    pathBusy,\n")
