import { describe, expect, it } from "vitest";
import type { LearningPath } from "@/lib/contracts/session";
import { ANON, makeDeps, seedSession } from "./test-helpers";
import { handleMovePart, movePart } from "./path";

const path: LearningPath = {
  topic: "Rome",
  parts: [
    { title: "A", summary: "a", status: "done" },
    { title: "B", summary: "b", status: "current" },
    { title: "C", summary: "c", status: "todo" },
    { title: "D", summary: "d", status: "todo" },
    { title: "E", summary: "e", status: "todo" },
  ],
};
const titles = (p: LearningPath) => p.parts.map((x) => x.title).join("");

describe("movePart", () => {
  it("reorders the parts still to come, never before the current one", () => {
    expect(titles(movePart(path, 4, 2))).toBe("ABECD");
    expect(titles(movePart(path, 2, 3))).toBe("ABDCE");
    expect(titles(movePart(path, 4, 0))).toBe("ABECD"); // clamped to the first open slot
  });

  it("refuses to move a done or current part", () => {
    expect(() => movePart(path, 1, 3)).toThrow(/haven't started/);
    expect(() => movePart(path, 0, 3)).toThrow(/haven't started/);
  });
});

describe("handleMovePart", () => {
  it("saves the new order", async () => {
    const deps = makeDeps();
    await seedSession(deps, { path });
    const { body } = await handleMovePart(deps, ANON, "s1", { from: 4, to: 2 });
    expect(titles(body.path)).toBe("ABECD");
    expect(titles((await deps.store.getSession("s1"))!.path!)).toBe("ABECD");
  });

  it("409s without a path", async () => {
    const deps = makeDeps();
    await seedSession(deps);
    await expect(handleMovePart(deps, ANON, "s1", { from: 1, to: 0 })).rejects.toMatchObject({ status: 409 });
  });
});
EOF
cat > components/PathCard.test.tsx <<'EOF'
// @vitest-environment jsdom
import { afterEach, describe, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { PathCard } from "./PathCard";

afterEach(cleanup);

const path = {
  topic: "The fall of the Roman Republic",
  parts: [
    { title: "The Gracchi", summary: "Reform and violence", status: "done" as const },
    { title: "Warlords", summary: "Sulla and Pompey", status: "current" as const },
    { title: "Caesar", summary: "The Rubicon", status: "todo" as const },
    { title: "Augustus", summary: "The principate", status: "todo" as const },
  ],
};

describe("PathCard", () => {
  it("shows the current part in one line, and the full path when opened", () => {
    render(<PathCard path={path} />);
    screen.getByText("Part 2 of 4: Warlords");
    expect(screen.queryByText("Reform and violence")).toBeNull();
    fireEvent.click(screen.getByRole("button", { name: /Part 2 of 4/ }));
    screen.getByText("Reform and violence");
    screen.getByText("now");
  });

  it("lets the learner reorder only the parts still to come", () => {
    const onMove = vi.fn();
    render(<PathCard path={path} onMove={onMove} />);
    fireEvent.click(screen.getByRole("button", { name: /Part 2 of 4/ }));
    expect(screen.queryByRole("button", { name: /Move “Warlords”/ })).toBeNull();
    fireEvent.click(screen.getByRole("button", { name: "Do “Augustus” next" }));
    expect(onMove).toHaveBeenCalledWith(3, 2);
    fireEvent.click(screen.getByRole("button", { name: "Move “Caesar” down" }));
    expect(onMove).toHaveBeenCalledWith(2, 3);
  });

  it("says when every part is done", () => {
    render(<PathCard path={{ ...path, parts: path.parts.map((p) => ({ ...p, status: "done" as const })) }} />);
    screen.getByText("All 4 parts done");
  });
});
EOF
